'use strict';

/**
 * Reads the credentials generated by globalSetup.js. It does not depend on the opentok package,
 * which cannot be loaded inside the Jest/Detox environment.
 */

const fs = require('fs');
const path = require('path');

const CREDENTIALS_PATH = path.join(__dirname, '../.e2e-credentials.json');

/** Reads the generated credentials file; throws if globalSetup did not create it. */
function readCredentials() {
  if (!fs.existsSync(CREDENTIALS_PATH)) {
    throw new Error(
      'E2E credentials not found. This usually means globalSetup failed.\n' +
      'Make sure E2E_API_KEY and E2E_API_SECRET environment variables are set.\n' +
      'Credentials file expected at: ' + CREDENTIALS_PATH
    );
  }
  return JSON.parse(fs.readFileSync(CREDENTIALS_PATH, 'utf8'));
}

/**
 * Returns the credentials of one of the sessions created by globalSetup.js.
 *
 * - `routed`: default session for most specs
 * - `relayed`: P2P session
 * - `moderation`: dedicated routed session for moderation specs, with a moderator bot token
 *
 * @param {'routed'|'relayed'|'moderation'} [name='routed']
 * @returns {Promise<{apiKey: string, apiSecret: string, apiUrl: string, jsSdkUrl: string, sessionId: string, tokenApp: string, botTokens: string[], mediaMode: string, moderatorBotToken?: string}>}
 */
async function getCredentials(name = 'routed') {
  const creds = readCredentials()[name];
  if (!creds) {
    throw new Error(`No '${name}' session in the generated E2E credentials.`);
  }
  return creds;
}

module.exports = { getCredentials };
